package com.bank.cost;

// A cost center with a net profit (positive) or loss (negative) value.
public class CostCenterNode {
    private final int profit;
    private CostCenterNode left;
    private CostCenterNode right;

    public CostCenterNode(int profit) {
        this.profit = profit;
    }

    public int getProfit() { return profit; }
    public CostCenterNode getLeft() { return left; }
    public CostCenterNode getRight() { return right; }
    public void setLeft(CostCenterNode left) { this.left = left; }
    public void setRight(CostCenterNode right) { this.right = right; }
}
