package com.bank.cost;

import java.util.logging.Logger;

// Finds the most profitable connected chain of cost centers.
public class MaxPathSumService {

    private static final Logger log = Logger.getLogger(MaxPathSumService.class.getName());

    private int maxSum;

    public int maxPathSum(CostCenterNode root) {
        maxSum = Integer.MIN_VALUE; // could be all losses
        gain(root);
        return maxSum;
    }

    // Returns the best upward gain through ONE child; updates global max.
    private int gain(CostCenterNode node) {
        if (node == null) {
            return 0;
        }
        // Drop loss-making branches by clamping to zero.
        int leftGain = Math.max(gain(node.getLeft()), 0);
        int rightGain = Math.max(gain(node.getRight()), 0);

        // Best path that BENDS here uses both children.
        maxSum = Math.max(maxSum, node.getProfit() + leftGain + rightGain);

        // Parent can only extend through ONE side.
        return node.getProfit() + Math.max(leftGain, rightGain);
    }

    public int mostProfitableChain(CostCenterNode root) {
        int best = maxPathSum(root);
        log.info(() -> "Most profitable connected cost-center chain = " + best);
        return best;
    }
}
