package com.bank.cost;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MaxPathSumDemo {

    private static final Logger log = Logger.getLogger(MaxPathSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Most Profitable Cost-Center Chain");

        //            -10
        //           /    \
        //          9      20
        //                /    \
        //              15      7
        // Best bending path: 15 + 20 + 7 = 42 (skips -10)
        CostCenterNode root = new CostCenterNode(-10);
        root.setLeft(new CostCenterNode(9));
        root.setRight(new CostCenterNode(20));
        root.getRight().setLeft(new CostCenterNode(15));
        root.getRight().setRight(new CostCenterNode(7));

        new MaxPathSumService().mostProfitableChain(root);
    }
}
